"""Write static/js/shared.gen.js: the constants the browser code shares with
the Python app, generated from app/common.py so the two can't drift apart.
tools/build_site.py runs this; run it by hand after changing those constants.
"""
from __future__ import annotations

import json
import sys
from pathlib import Path

ROOT = Path(__file__).resolve().parent.parent
OUT = ROOT / "static" / "js" / "shared.gen.js"


def main() -> None:
    sys.path.insert(0, str(ROOT))
    from app.common import BIBLE_TRACKS, EVERYDAY_DOMAINS, FORM_OF
    OUT.write_text(
        "// Generated by tools/gen_shared.py from app/common.py. Do not edit.\n"
        f"export const EVERYDAY_DOMAINS = {json.dumps(list(EVERYDAY_DOMAINS))};\n"
        f"export const BIBLE_TRACKS = {json.dumps(list(BIBLE_TRACKS))};\n"
        f"export const FORM_OF = new RegExp({json.dumps(FORM_OF.pattern)}, \"i\");\n",
        encoding="utf-8")


if __name__ == "__main__":
    main()
